library(optparse); library(dplyr); library(ggplot2); library(logistf)
if (!requireNamespace("kernelshap", quietly=TRUE)) stop("Package 'kernelshap' is required")
option_list <- list(make_option(c("--habs_file"),type="character",default="HABS_Baseline_Integrated.csv"),make_option(c("--output_dir"),type="character",default="./step17_results"),make_option(c("--ptau_col"),type="character",default="pTau217_Primary"),make_option(c("--sample_size"),type="integer",default=500),make_option(c("--seed"),type="integer",default=42))
opt<-parse_args(OptionParser(option_list=option_list));dir.create(opt$output_dir,recursive=TRUE,showWarnings=FALSE);set.seed(opt$seed)
h<-read.csv(opt$habs_file,stringsAsFactors=FALSE,check.names=FALSE);if(!opt$ptau_col%in%names(h))stop("pTau217 column not found")
d<-h%>%mutate(Age=as.numeric(Age),Gender=factor(Gender),APOE4_Positive=as.numeric(APOE4_Positive),pTau217=as.numeric(.data[[opt$ptau_col]]),AD_Conversion=as.numeric(AD_Conversion))%>%select(Age,Gender,APOE4_Positive,pTau217,AD_Conversion)%>%na.omit()
fit<-logistf(AD_Conversion~Age+Gender+APOE4_Positive+pTau217,data=d);predict_prob<-function(object,newdata)as.numeric(predict(object,newdata=newdata,type="response"));x<-d%>%select(Age,Gender,APOE4_Positive,pTau217);if(nrow(x)>opt$sample_size){i<-sample(seq_len(nrow(x)),opt$sample_size);x<-x[i,,drop=FALSE]}
sh<-kernelshap::kernelshap(object=fit,X=x,pred_fun=predict_prob);imp<-data.frame(Feature=names(x),MeanAbsSHAP=colMeans(abs(sh$S)))%>%arrange(desc(MeanAbsSHAP));write.csv(imp,file.path(opt$output_dir,"step17_shap_importance.csv"),row.names=FALSE);write.csv(as.data.frame(sh$S),file.path(opt$output_dir,"step17_shap_matrix.csv"),row.names=FALSE)
ggsave(file.path(opt$output_dir,"step17_shap_importance.pdf"),ggplot(imp,aes(x=reorder(Feature,MeanAbsSHAP),y=MeanAbsSHAP))+geom_col(fill="steelblue")+coord_flip()+theme_minimal()+xlab(NULL)+ylab("Mean |SHAP|"),width=7,height=5)
writeLines(c(sprintf("Samples used: %d",nrow(x)),sprintf("Top feature: %s",imp$Feature[1])),file.path(opt$output_dir,"step17_summary.txt"));cat("Saved SHAP outputs\n")
